import { type ComponentProps, useMemo } from 'react';
import {
  ArcElement,
  BarElement,
  CategoryScale,
  Chart as ChartJS,
  Legend,
  LinearScale,
  LineElement,
  PointElement,
  RadialLinearScale,
  Title as TitlePlugin,
  Tooltip,
} from 'chart.js';
import {
  Bar,
  Bubble,
  Doughnut,
  Line,
  Pie,
  PolarArea,
  Radar,
  Scatter,
} from 'react-chartjs-2';
import type { ToolComponentProps } from '../../AIMarkdown';
import { useTranslationContext } from '../../../../../context/TranslationContext';
import { chartJsSchema } from './chartJsSchema';

// react-chartjs-2 registers each chart type's controller, but not the scales those controllers
// default to: `radar` and `polarArea` need `RadialLinearScale`.
ChartJS.register(
  ArcElement,
  Tooltip,
  Legend,
  CategoryScale,
  LinearScale,
  RadialLinearScale,
  BarElement,
  LineElement,
  PointElement,
  TitlePlugin,
);

const UnknownChart = () => {
  const { t } = useTranslationContext();
  return <div>{t('aiComponents.chart.unknownType.text', 'Unknown chart type')}</div>;
};

const components = {
  bar: Bar,
  bubble: Bubble,
  doughnut: Doughnut,
  line: Line,
  pie: Pie,
  polarArea: PolarArea,
  radar: Radar,
  scatter: Scatter,
  unknown: UnknownChart,
} as const;

const Chart = ({ data, fallback }: ToolComponentProps) => {
  const parsedDataOrError = useMemo(() => {
    try {
      return chartJsSchema.parse(JSON.parse(data));
    } catch (error) {
      if (error instanceof Error) {
        error.message = `Error occured while parsing Chart.js data: ${error.message}`;
        return error;
      }
      return new Error('Unknown error occured while parsing Chart.js data');
    }
  }, [data]);

  if (parsedDataOrError instanceof Error) {
    return fallback;
  }

  const Component =
    components[parsedDataOrError.type as keyof typeof components] ?? components.unknown;

  return (
    <div className='str-chat__ai-chart'>
      <Component data={parsedDataOrError.data} options={{ responsive: true }} />
    </div>
  );
};

export type ChartProps = ComponentProps<typeof Chart>;

export default Chart;

// Usage: an app rendering these messages can render Chart.js charts. To render one, return a
// markdown code block with language "chartjs" that holds JSON of Chart.js compatible data.
